"use client";

/**
 * Message bubbles: a phone thread where someone shares a link to a product
 * video and the replies come back, each one after a few beats of typing dots.
 * The word-of-mouth beat of a launch film.
 *
 * Written by Better Design. Painted from the theme prop.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import type { ReactNode } from "react";
import { AbsoluteFill, Img, interpolate, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { easings, pickFont, type VideoTheme, springs, useVideoTheme, withAlpha, srcOf } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["400", "500", "600", "700"], subsets: ["latin"] });

const LINK_AT = 12;
/** Frames of typing dots before each reply from the other side. */
const TYPING_FRAMES = 22;
/** Frames between two messages from the same side. */
const GAP_FRAMES = 14;

export interface MessageBubblesProps {
  /** The thread after the link. Each entry starts with "me:" or "them:". */
  messages?: string[];
  /** The person on the other side of the thread. */
  contact?: string;
  /** Title on the shared link preview. */
  videoTitle?: string;
  /** Address on the shared link preview. */
  videoUrl?: string;
  /** Optional poster picture for the link preview. A drawn frame stands in when absent. */
  poster?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

interface Line { mine: boolean; text: string; at: number; typingAt?: number }

const parse = (entry: string): { mine: boolean; text: string } => {
  const m = /^\s*(me|them)\s*:\s*/i.exec(entry);
  return m ? { mine: m[1]!.toLowerCase() === "me", text: entry.slice(m[0].length) } : { mine: false, text: entry };
};

/** When each message lands. Replies from the other side wait out the typing dots first. */
const schedule = (messages: string[]): Line[] => {
  let t = LINK_AT + 20;
  return messages.map((entry) => {
    const { mine, text } = parse(entry);
    if (mine) {
      t += GAP_FRAMES;
      return { mine, text, at: t };
    }
    const typingAt = t + 6;
    t = typingAt + TYPING_FRAMES;
    return { mine, text, at: t, typingAt };
  });
};

const DEFAULT_MESSAGES = [
  "me: You have to see this launch film.",
  "them: Wait, this is so good",
  "them: Who made it?",
  "me: Their team did, in one afternoon.",
  "them: Sending it to everyone right now",
];

/** A phone thread: a video link goes out, replies come back. */
export function MessageBubbles({
  messages = DEFAULT_MESSAGES,
  contact = "Alex",
  videoTitle = "Meet your product in 60 seconds",
  videoUrl = "yourproduct.com/film",
  poster,
  theme: themeOverride,
  font,
}: MessageBubblesProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const family = pickFont(font, theme, INTER);
  const lines = schedule(messages);

  const pop = (at: number) => spring({ frame: frame - at, fps, config: springs.snappy });
  const phoneT = easings.out(interpolate(frame, [0, 18], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }));
  const radius = theme.radius * 2.8;

  const bubble = (mine: boolean, p: number, children: ReactNode) => (
    <div
      style={{
        alignSelf: mine ? "flex-end" : "flex-start", maxWidth: "78%", padding: "18px 24px", borderRadius: radius,
        borderBottomRightRadius: mine ? 8 : radius, borderBottomLeftRadius: mine ? radius : 8,
        background: mine ? theme.primary : theme.muted, color: mine ? theme.primaryForeground : theme.foreground,
        fontSize: 30, lineHeight: 1.3, fontWeight: 500,
        opacity: Math.min(p * 2, 1), transform: `scale(${0.6 + 0.4 * p})`, transformOrigin: mine ? "100% 100%" : "0% 100%",
      }}
    >
      {children}
    </div>
  );

  const linkP = pop(LINK_AT);

  // Each message opens its own row from zero height, so the thread scrolls up smoothly as it grows.
  const slot = (key: string | number, open: number, children: ReactNode) => (
    <div key={key} style={{ display: "grid", gridTemplateRows: `${Math.min(open * 1.6, 1)}fr`, flexShrink: 0 }}>
      <div style={{ minHeight: 0, display: "flex", flexDirection: "column", paddingTop: 12 }}>{children}</div>
    </div>
  );

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family, alignItems: "center", justifyContent: "center" }}>
      <div
        style={{
          width: 600, height: 1000, borderRadius: 72, padding: 14, background: theme.border,
          boxShadow: `0 40px 80px oklch(0 0 0 / 0.16)`,
          opacity: phoneT, transform: `translateY(${(1 - phoneT) * 60}px)`,
        }}
      >
        <div style={{ width: "100%", height: "100%", borderRadius: 60, background: theme.card, overflow: "hidden", display: "flex", flexDirection: "column" }}>
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 10, padding: "44px 0 22px", borderBottom: `1px solid ${theme.border}` }}>
            <div style={{ width: 72, height: 72, borderRadius: 36, background: withAlpha(theme.primary, 0.14), color: theme.primary, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 30, fontWeight: 600 }}>
              {contact.trim().charAt(0).toUpperCase()}
            </div>
            <div style={{ fontSize: 24, fontWeight: 600, color: theme.foreground }}>{contact}</div>
          </div>

          <div style={{ flex: 1, minHeight: 0, overflow: "hidden", display: "flex", flexDirection: "column", justifyContent: "flex-end", padding: "0 26px 30px" }}>
            {slot("link", linkP, bubble(true, linkP,
              <div style={{ display: "flex", flexDirection: "column", gap: 14, width: 360 }}>
                <div style={{ position: "relative", height: 170, borderRadius: radius * 0.7, overflow: "hidden", background: withAlpha(theme.primaryForeground, 0.16) }}>
                  {poster ? (
                    <Img src={srcOf(poster)} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                  ) : (
                    <div style={{ position: "absolute", left: 24, top: 26, display: "flex", flexDirection: "column", gap: 10 }}>
                      <div style={{ width: 150, height: 14, borderRadius: 7, background: withAlpha(theme.primaryForeground, 0.5) }} />
                      <div style={{ width: 96, height: 14, borderRadius: 7, background: withAlpha(theme.primaryForeground, 0.3) }} />
                    </div>
                  )}
                  <div style={{ position: "absolute", left: "50%", top: "50%", width: 68, height: 68, marginLeft: -34, marginTop: -34, borderRadius: 34, background: theme.primaryForeground, display: "flex", alignItems: "center", justifyContent: "center" }}>
                    <div style={{ width: 0, height: 0, marginLeft: 6, borderTop: "13px solid transparent", borderBottom: "13px solid transparent", borderLeft: `20px solid ${theme.primary}` }} />
                  </div>
                </div>
                <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                  <div style={{ fontSize: 26, fontWeight: 600 }}>{videoTitle}</div>
                  <div style={{ fontSize: 22, fontWeight: 400, opacity: 0.75 }}>{videoUrl}</div>
                </div>
              </div>,
            ))}

            {lines.map((line, i) => {
              if (frame < (line.typingAt ?? line.at)) return null;
              if (line.typingAt !== undefined && frame < line.at) {
                const p = pop(line.typingAt);
                return slot(i, p,
                  <div style={{ alignSelf: "flex-start", display: "flex", gap: 8, padding: "22px 24px", borderRadius: radius, borderBottomLeftRadius: 8, background: theme.muted, opacity: Math.min(p * 2, 1), transform: `scale(${0.6 + 0.4 * p})`, transformOrigin: "0% 100%" }}>
                    {[0, 1, 2].map((d) => {
                      const wave = (Math.sin((frame - line.typingAt! - d * 3) / 3.2) + 1) / 2;
                      return <div key={d} style={{ width: 13, height: 13, borderRadius: 7, background: theme.mutedForeground, opacity: 0.35 + wave * 0.65, transform: `translateY(${-wave * 4}px)` }} />;
                    })}
                  </div>,
                );
              }
              return slot(i, line.typingAt !== undefined ? 1 : pop(line.at), bubble(line.mine, pop(line.at), line.text));
            })}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
}
